    static HaciendaRsException lastErrorException(final int errCode, final String msg) {
        return HaciendaRsException.withNativeCode(switch (errCode) {
            case 1 -> new ConversionErrorException(msg);
            case 2 -> new CoreErrorException(msg);
            case 3 -> new PanicException(msg);
            case 5 -> new OperationCancelledException(msg);
            default -> new HaciendaRsException(errCode, msg);
        }, errCode);
    }


